#include "cpp_mat_ipc_support.hpp"
using namespace mat_ipc;
int runIpcTests(){
    std::vector<std::string> passed;auto test=[&](const char* name,auto fn){fn();passed.emplace_back(name);};
    auto fresh=[](){auto s=std::make_unique<Shared>();initialize(*s,1,42,11,22);return s;};
    auto packet=[](){auto p=std::make_unique<Packet>();p->domain=1;p->header={0,480,1,0,1,2};p->calls[0].header={1,0,1,7,{.25f,.5f,.75f},480};p->calls[0].pcm.fill(.125f);return p;};
    test("fixed_layout_contract_matches_only_exact_ABI",[&]{auto s=fresh();check(validate(s->contract,1,42,11,22,GetCurrentProcessId())==Error::none,"contract");});
    for(auto field:std::vector<std::string>{"version","length","capacity","call_size","frequency","reserved"})test(("reject_contract_"+field).c_str(),[&]{auto s=fresh();auto& c=s->contract;if(field=="version")++c.version;if(field=="length")--c.mapBytes;if(field=="capacity")++c.capacity;if(field=="call_size")--c.callBytes;if(field=="frequency")c.qpcHz=0;if(field=="reserved")c.reserved=1;check(validate(c,1,42,11,22,GetCurrentProcessId())==Error::badContract,"bad contract accepted");});
    test("domain_epoch_nonce_owner_identity_guard",[&]{auto s=fresh();check(validate(s->contract,2,42,11,22,GetCurrentProcessId())==Error::identity&&validate(s->contract,1,43,11,22,GetCurrentProcessId())==Error::identity&&validate(s->contract,1,42,12,22,GetCurrentProcessId())==Error::identity&&validate(s->contract,1,42,11,22,0)==Error::identity,"stale identity");});
    test("owned_copy_PCM_XYZ_and_interlocked_publish_receive",[&]{auto s=fresh();auto p=packet(),out=std::make_unique<Packet>();check(send(*s,*p,qpc()),"send");p->calls[0].pcm.fill(.9f);p->calls[0].header.xyz[0]=99;int64_t when;check(receive(*s,*out,when)==Poll::item&&out->calls[0].pcm[0]==.125f&&out->calls[0].header.xyz[0]==.25f&&when>0&&get(s->reader.read)==1,"copy/advance");});
    test("exact_32_capacity_33rd_fails_no_overwrite",[&]{auto s=fresh();auto p=packet();for(unsigned n=0;n<32;++n){p->header.index=n;check(send(*s,*p,qpc()),"capacity");}check(!send(*s,*p,qpc())&&error(*s)==Error::overflow&&get(s->writer.write)==32,"overflow lost");});
    test("ring_wrap_1000_ordered_frames",[&]{auto s=fresh();auto p=packet(),out=std::make_unique<Packet>();for(unsigned n=0;n<1000;++n){p->header.index=n;p->calls[0].pcm[0]=n*.0001f;check(send(*s,*p,qpc()),"wrap push");int64_t when;check(receive(*s,*out,when)==Poll::item&&out->header.index==n&&out->calls[0].pcm[0]==p->calls[0].pcm[0],"wrap order");}});
    for(auto kind:std::vector<std::string>{"length","count","checksum","sequence","epoch","kind"})test(("reject_message_"+kind).c_str(),[&]{auto s=fresh();auto p=packet(),out=std::make_unique<Packet>();check(send(*s,*p,qpc()),"send");auto& m=s->slots[0].header;if(kind=="length")m.bytes=1;if(kind=="count")m.calls=65;if(kind=="checksum")s->slots[0].calls[0].pcm[0]=.5f;if(kind=="sequence")++m.sequence;if(kind=="epoch")++m.epoch;if(kind=="kind")m.kind=99;int64_t when;check(receive(*s,*out,when)==Poll::failed&&error(*s)!=Error::none&&get(s->reader.read)==0,"invalid payload read/published");});
    test("counter_corruption_rejected_before_indexing",[&]{auto s=fresh();auto out=std::make_unique<Packet>();put(s->reader.read,1);int64_t when;check(receive(*s,*out,when)==Poll::failed&&error(*s)==Error::counters,"counter bounds");});
    test("EOF_is_control_and_prevents_more_sends",[&]{auto s=fresh();auto p=packet(),out=std::make_unique<Packet>();p->header.flags=1;p->calls[0].header.flags=8;p->calls[0].pcm.fill(0);check(send(*s,*p,qpc())&&!send(*s,*p,qpc()),"post EOF push");int64_t when;check(receive(*s,*out,when)==Poll::item&&out->header.flags==1&&get(s->common.producerDone)==1,"EOF missing");});
    test("first_error_wins_and_cancel_stops_both_sides",[&]{auto s=fresh();auto p=packet(),out=std::make_unique<Packet>();fail(*s,Error::producerExited);fail(*s,Error::cancelled);int64_t when;check(error(*s)==Error::producerExited&&!send(*s,*p,qpc())&&receive(*s,*out,when)==Poll::failed,"fault overwrite");});
    std::cout<<Json({{"ipc_protocol_tests_passed",passed.size()},{"tests",passed},{"native_encoder_called",false}}).dump(2)<<'\n';return 0;
}
